*{margin:0;padding:0;box-sizing:border-box}
:root{--primary:#6366f1;--secondary:#8b5cf6;--dark:#0f172a;--light:#f8fafc;--accent:#ec4899;--text:#334155;--gradient:linear-gradient(135deg,var(--primary),var(--secondary),var(--accent))}
body{font-family:'Segoe UI',system-ui,-apple-system,sans-serif;background:var(--light);color:var(--text);overflow-x:hidden;line-height:1.6}
.container{max-width:1400px;margin:0 auto;padding:0 2rem}
header{position:fixed;top:0;left:0;right:0;z-index:1000;background:rgba(15,23,42,0.95);backdrop-filter:blur(10px);padding:1rem 0;transition:all 0.3s}
nav{display:flex;justify-content:space-between;align-items:center}
.logo{font-size:1.5rem;font-weight:700;background:var(--gradient);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.nav-links{display:flex;gap:2rem;list-style:none}
.nav-links a{color:var(--light);text-decoration:none;transition:color 0.3s;position:relative}
.nav-links a:hover{color:var(--primary)}
.nav-links a::after{content:'';position:absolute;bottom:-5px;left:0;width:0;height:2px;background:var(--gradient);transition:width 0.3s}
.nav-links a:hover::after{width:100%}
.menu-toggle{display:none;background:none;border:none;color:var(--light);font-size:1.5rem;cursor:pointer}
section{min-height:100vh;padding:5rem 0;opacity:0;transform:translateY(50px);transition:all 0.8s}
section.visible{opacity:1;transform:translateY(0)}
.hero{display:flex;align-items:center;justify-content:space-between;background:var(--dark);color:var(--light);position:relative;overflow:hidden}
.hero::before{content:'';position:absolute;width:500px;height:500px;background:var(--gradient);opacity:0.1;border-radius:50%;top:-100px;right:-100px;animation:pulse 4s infinite}
.hero-content{flex:1;z-index:1}
.hero h1{font-size:4rem;margin-bottom:1rem;background:var(--gradient);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:slideIn 1s}
.hero p{font-size:1.3rem;margin-bottom:2rem;color:#94a3b8}
.hero-image{flex:1;display:flex;justify-content:center;align-items:center}
.hero-circle{width:400px;height:400px;background:var(--gradient);border-radius:50%;animation:float 3s ease-in-out infinite;display:flex;align-items:center;justify-content:center;font-size:3rem}
.btn{display:inline-block;padding:1rem 2rem;background:var(--gradient);color:white;text-decoration:none;border-radius:50px;transition:all 0.3s;border:none;cursor:pointer;font-size:1rem;font-weight:600}
.btn:hover{transform:translateY(-3px);box-shadow:0 10px 30px rgba(99,102,241,0.4)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:2rem;margin-top:3rem}
.card{background:white;padding:2rem;border-radius:20px;box-shadow:0 10px 30px rgba(0,0,0,0.1);transition:all 0.3s;position:relative;overflow:hidden}
.card::before{content:'';position:absolute;top:0;left:0;width:100%;height:5px;background:var(--gradient);transform:scaleX(0);transition:transform 0.3s}
.card:hover::before{transform:scaleX(1)}
.card:hover{transform:translateY(-10px);box-shadow:0 20px 40px rgba(0,0,0,0.15)}
.card h3{margin-bottom:1rem;color:var(--dark);font-size:1.5rem}
.card p{color:var(--text);line-height:1.8}
.section-title{text-align:center;font-size:3rem;margin-bottom:3rem;background:var(--gradient);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.skills{background:white}
.skill-item{background:var(--light);padding:1.5rem;border-radius:15px;text-align:center;transition:all 0.3s}
.skill-item:hover{background:var(--gradient);color:white;transform:scale(1.05)}
.skill-icon{font-size:3rem;margin-bottom:1rem}
.projects{background:var(--light)}
.project-card{position:relative;height:400px;border-radius:20px;overflow:hidden;cursor:pointer}
.project-image{width:100%;height:100%;object-fit:cover;transition:transform 0.5s}
.project-overlay{position:absolute;bottom:0;left:0;right:0;background:linear-gradient(transparent,rgba(0,0,0,0.9));padding:2rem;transform:translateY(100%);transition:transform 0.5s}
.project-card:hover .project-image{transform:scale(1.1)}
.project-card:hover .project-overlay{transform:translateY(0)}
.project-overlay h3{color:white;margin-bottom:0.5rem}
.project-overlay p{color:#cbd5e1}
.contact{background:var(--dark);color:var(--light)}
.contact-form{max-width:600px;margin:0 auto}
.form-group{margin-bottom:1.5rem}
.form-group label{display:block;margin-bottom:0.5rem;color:var(--light)}
.form-group input,.form-group textarea{width:100%;padding:1rem;border:2px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.05);border-radius:10px;color:var(--light);font-size:1rem;transition:all 0.3s}
.form-group input:focus,.form-group textarea:focus{outline:none;border-color:var(--primary);background:rgba(255,255,255,0.1)}
.form-group textarea{resize:vertical;min-height:150px}
footer{background:var(--dark);color:var(--light);text-align:center;padding:2rem 0;border-top:1px solid rgba(255,255,255,0.1)}
.social-links{display:flex;justify-content:center;gap:1rem;margin-bottom:1rem}
.social-links a{width:50px;height:50px;background:var(--gradient);border-radius:50%;display:flex;align-items:center;justify-content:center;color:white;text-decoration:none;transition:all 0.3s}
.social-links a:hover{transform:translateY(-5px);box-shadow:0 10px 20px rgba(99,102,241,0.4)}
.modal{display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.9);z-index:2000;align-items:center;justify-content:center;padding:2rem}
.modal.active{display:flex}
.modal-content{background:white;padding:3rem;border-radius:20px;max-width:600px;width:100%;position:relative;animation:modalSlide 0.3s}
.modal-close{position:absolute;top:1rem;right:1rem;background:none;border:none;font-size:2rem;cursor:pointer;color:var(--text)}
@keyframes slideIn{from{opacity:0;transform:translateX(-50px)}to{opacity:1;transform:translateX(0)}}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-20px)}}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.1)}}
@keyframes modalSlide{from{transform:scale(0.8);opacity:0}to{transform:scale(1);opacity:1}}
@media(max-width:768px){.hero{flex-direction:column;text-align:center}.hero h1{font-size:2.5rem}.hero-circle{width:250px;height:250px}.nav-links{position:fixed;top:70px;left:0;right:0;background:var(--dark);flex-direction:column;padding:2rem;transform:translateX(-100%);transition:transform 0.3s}.nav-links.active{transform:translateX(0)}.menu-toggle{display:block}.grid{grid-template-columns:1fr}.section-title{font-size:2rem}}
.loader{position:fixed;top:0;left:0;right:0;bottom:0;background:var(--dark);z-index:9999;display:flex;align-items:center;justify-content:center;transition:opacity 0.5s}
.loader-circle{width:100px;height:100px;border:5px solid rgba(255,255,255,0.1);border-top-color:var(--primary);border-radius:50%;animation:spin 1s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.loader.hidden{opacity:0;pointer-events:none}
.stats{display:flex;justify-content:space-around;margin:3rem 0;flex-wrap:wrap}
.stat-item{text-align:center;padding:2rem}
.stat-number{font-size:3rem;font-weight:700;background:var(--gradient);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;display:block}
.stat-label{color:var(--text);margin-top:0.5rem}
.parallax{position:relative;background-attachment:fixed;background-size:cover;background-position:center}
.testimonials{background:white}
.testimonial-card{background:var(--light);padding:2rem;border-radius:20px;position:relative;margin-top:2rem}
.testimonial-card::before{content:'"';position:absolute;top:-20px;left:20px;font-size:5rem;color:var(--primary);opacity:0.2}
.testimonial-text{font-style:italic;margin-bottom:1rem;color:var(--text)}
