.author-avatar{width:50px;height:50px;border-radius:50%;background:var(--gradient)}
.author-info h4{color:var(--dark);margin-bottom:0.2rem}
.author-info p{color:var(--text);font-size:0.9rem}
.timeline{position:relative;padding:2rem 0}
.timeline::before{content:'';position:absolute;left:50%;top:0;bottom:0;width:2px;background:var(--gradient)}
.timeline-item{display:flex;justify-content:space-between;margin-bottom:3rem;position:relative}
.timeline-content{width:45%;background:white;padding:2rem;border-radius:15px;box-shadow:0 5px 20px rgba(0,0,0,0.1)}
.timeline-dot{position:absolute;left:50%;transform:translateX(-50%);width:20px;height:20px;background:var(--gradient);border-radius:50%;border:5px solid var(--light)}
.timeline-item:nth-child(even) .timeline-content{margin-left:auto}
@media(max-width:768px){.timeline::before{left:20px}.timeline-content{width:calc(100% - 60px);margin-left:60px!important}.timeline-dot{left:20px}}
.pricing{background:var(--light)}
