<script>
window.addEventListener('load',()=>{
setTimeout(()=>{
document.querySelector('.loader').classList.add('hidden');
},1000);
});
const sections=document.querySelectorAll('section');
const navLinks=document.querySelectorAll('.nav-links a');
const observer=new IntersectionObserver((entries)=>{
entries.forEach(entry=>{
if(entry.isIntersecting){
entry.target.classList.add('visible');
const id=entry.target.getAttribute('id');
navLinks.forEach(link=>{
link.style.color=link.getAttribute('href')==='#'+id?'var(--primary)':'var(--light)';
});
}
});
},{threshold:0.1});
sections.forEach(section=>{
observer.observe(section);
});
const menuToggle=document.querySelector('.menu-toggle');
const navLinksContainer=document.querySelector('.nav-links');
menuToggle.addEventListener('click',()=>{
navLinksContainer.classList.toggle('active');
});
navLinks.forEach(link=>{
link.addEventListener('click',()=>{
navLinksContainer.classList.remove('active');
});
});
document.querySelectorAll('a[href^="#"]').forEach(anchor=>{
anchor.addEventListener('click',function(e){
e.preventDefault();
const target=document.querySelector(this.getAttribute('href'));
if(target){
const offsetTop=target.offsetTop-70;
window.scrollTo({
top:offsetTop,
behavior:'smooth'
});
}
});
});
const statNumbers=document.querySelectorAll('.stat-number');
let animated=false;
const animateStats=()=>{
if(animated)return;
statNumbers.forEach(stat=>{
const target=parseInt(stat.getAttribute('data-target'));
const duration=2000;
const increment=target/(duration/16);
let current=0;
const updateNumber=()=>{
current+=increment;
if(current<target){
stat.textContent=Math.floor(current);
requestAnimationFrame(updateNumber);
}else{
stat.textContent=target;
}
};
updateNumber();
});
animated=true;
};
const statsObserver=new IntersectionObserver((entries)=>{
entries.forEach(entry=>{
if(entry.isIntersecting){
animateStats();
}
});
},{threshold:0.5});
const statsSection=document.querySelector('.stats');
if(statsSection){
statsObserver.observe(statsSection);
}
function openModal(){
document.getElementById('modal').classList.add('active');
document.body.style.overflow='hidden';
}
function closeModal(){
document.getElementById('modal').classList.remove('active');
document.body.style.overflow='auto';
}
window.addEventListener('click',(e)=>{
const modal=document.getElementById('modal');
if(e.target===modal){
closeModal();
}
});
function handleSubmit(e){
e.preventDefault();
alert('Köszönjük az üzenetét! Hamarosan felvesszük Önnel a kapcsolatot.');
e.target.reset();
}
function handleModalSubmit(e){
e.preventDefault();
alert('Köszönjük! Hamarosan felvesszük Önnel a kapcsolatot.');
closeModal();
e.target.reset();
}
let lastScroll=0;
const header=document.querySelector('header');
window.addEventListener('scroll',()=>{
const currentScroll=window.pageYOffset;
if(currentScroll>lastScroll&&currentScroll>100){
header.style.transform='translateY(-100%)';
}else{
header.style.transform='translateY(0)';
}
lastScroll=currentScroll;
});
const cards=document.querySelectorAll('.card');
cards.forEach((card,index)=>{
card.style.animationDelay=`${index*0.1}s`;
});
document.addEventListener('mousemove',(e)=>{
const mouseX=e.clientX/window.innerWidth;
const mouseY=e.clientY/window.innerHeight;
document.querySelector('.hero::before')?.style.setProperty('transform',`translate(${mouseX*50}px,${mouseY*50}px)`);
});
const faqItems=document.querySelectorAll('.faq-item');
faqItems.forEach(item=>{
item.addEventListener('click',()=>{
item.classList.toggle('active');
});
});
if('IntersectionObserver' in window){
const fadeElements=document.querySelectorAll('.card, .skill-item, .project-card');
const fadeObserver=new IntersectionObserver((entries)=>{
entries.forEach(entry=>{
if(entry.isIntersecting){
entry.target.style.opacity='1';
entry.target.style.transform='translateY(0)';
}
});
},{threshold:0.1});
fadeElements.forEach(el=>{
el.style.opacity='0';
el.style.transform='translateY(30px)';
el.style.transition='opacity 0.6s, transform 0.6s';
fadeObserver.observe(el);
});
}
</script>
